"}, "risk_level": "R1", "schema_version": 1, "source_commit": "a04446e57ec1fbc252a871afcec7752fb2807b14", "source_math_hash": "sha256:44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a", "source_status": "CURRENT", "source_structure_hash": "sha256:b4145c8f45416bb3b657b116ec4beae750bf4fada2118d90ccf08485391f32cf", "source_text": "The resolution property for schemes and stacks", "source_text_hash": "sha256:95ed7e03ecc11d1bd09115a4ee437a99e66b44b122ef649d489206262e498250", "unit_id": "tag:04UZ:item003"}
{"chapter": "guide", "node_kind": "quote", "parent_tag": "04UZ", "placeholders": {"MATH_0001": "$\mathcal{X}$", "MATH_0002": "$\mathcal{X}$", "MATH_0003": "$\mathcal{X} = [Y/\text{GL}_n]$", "MATH_0004": "$Y$", "MATH_0005": "$\mathcal{X}$", "MATH_0006": "$\mathcal{X} = [\Spec(A)/G]$", "MATH_0007": "$G$", "MATH_0008": "$k$", "MATH_0009": "$\mathcal{X}$", "MATH_0010": "$I_\mathcal{X} \to \mathcal{X}$", "MATH_0011": "$\mathcal{X}$", "MATH_0012": "$\mathcal{X}$", "MATH_0013": "$\mathcal{X}$"}, "render": {"prefix": "", "suffix": "
